with reviewed(id, patch) as (
  values
    (418::bigint, jsonb_build_object(
      'queue_wait', 'Glam runs on Buenos Aires time: advertised opening can slide, and guests report waiting well past the stated door on some nights. Thursday uses one room and is lighter; the two-floor weekend format absorbs crowds better. Confirm the list or presale and do not build a tight schedule around 01:00.',
      'best_nights', 'Thursday is cheaper and more compact; Friday and Saturday unlock both rooms, so pop and reggaetón can coexist with dance, house or trance. Recent guests value having space to move, clean bathrooms and a smoking patio. Pick the music split, then arrive after the city has warmed up.',
      'crowd_mix', 'Gay men are central, joined by queer women, straight friends, young locals and tourists. The two rooms create different micro-crowds rather than one uniform floor. It is openly LGBT and social, with enough mainstream crossover that visitors should expect flirtation and friendship beyond a single label.',
      'dress_code', 'Contemporary club casual works: trainers, fitted shirts, crop tops and a stronger weekend look. No strict formal code is published. Dress for two warm rooms and keep valuables zipped; recent reviews praise personal space, but older and current reports still justify ordinary late-club caution.',
      'staff_inclusivity', 'The newest review pattern is encouraging: attentive staff, respectful dancers, active bathroom cleaning and security visible in the crowd. Other guests describe rude moments, weak drinks or tourist pricing. Clarify cover and promotions at the door, and ask for a supervisor if treatment changes.',
      'venue_classification', 'active_buenos_aires_lgbt_dance_club_at_cabrera_3046_with_one_room_thursday_two_room_weekends_pop_reggaeton_dance_house_trance_smoking_patio_mixed_queer_crowd_and_recent_positive_staff_cleanliness_consensus',
      'identity_note', 'Current listings place Glam Disco at José Antonio Cabrera 3046. The stored Avenida Córdoba 3199 address is outdated or incorrect and should not drive navigation.',
      'source_urls', to_jsonb(array['https://www.facebook.com/GlamDiscoBsAs/','https://wanderlog.com/place/details/2385309/glam-disco','https://qlist.app/venues/Buenos-Aires/Glam-Disco/aUZ5WTdSQjlIaGt3OG1qaC9qcWhkZw','https://www.tripadvisor.com/Attraction_Review-g312741-d10002046-Reviews-Glam_Disco-Buenos_Aires_Capital_Federal_District.html','https://whereis.gay/glam-disco']::text[]),
