    (422::bigint, jsonb_build_object(
      'queue_wait', 'Entry is straightforward rather than club-like: pay, receive a towel and locker, then choose your own pace through three large levels. Friday afternoon can be packed, while opening hours are calmer. Arrive with time to shower and orient yourself; this sprawling place rewards patience more than rushing.',
      'best_nights', 'Afternoons are the real rhythm, with Friday repeatedly reported as busy and weekends adding younger men to the established crowd. Daylight also opens the terrace. Come earlier for sauna and conversation; come later for a denser maze, cabins and darkroom experience before the 22:00 close.',
      'crowd_mix', 'The men-only crowd is mostly local and spans wide ages, with a visible older and bear presence and younger guests appearing more on weekends. Travellers say it is sociable and low-attitude rather than polished. The size means each bar, terrace and cruising zone can feel like a different scene.',
      'dress_code', 'Your towel is the practical dress code inside; bring easy clothes for lockers and shower sandals if you prefer them. This is a sauna and sexual space, not a fashion door. Condoms and lubricant are reported as provided, but carry your own backup and treat every cabin encounter as consent-specific.',
      'staff_inclusivity', 'Staff are repeatedly described as friendly, attentive and discreet. The serious weakness is upkeep: recent guests flag broken showers or cabin fittings, worn furniture and inconsistent hot water or cleaning. Check facilities before settling in and report hazards rather than accepting them as atmosphere.',
      'venue_classification', 'active_large_three_level_men_only_gay_sauna_at_gascon_956_with_bar_terrace_steam_dry_sauna_cabins_cinema_darkroom_broad_age_bear_local_crowd_friendly_staff_and_significant_maintenance_concerns',
      'identity_note', 'HomoSapiens is active at Gascón 956 in Buenos Aires, beside Amerika. The stored Lobos address is a geocoding error; the current operator account and independent guides all identify the Almagro/Villa Crespo property.',
      'source_urls', to_jsonb(array['https://www.instagram.com/homosapiensspaok/','https://www.travelgay.com/venue/homo-sapiens-buenos-aires','https://qlist.app/venues/Buenos-Aires/HomoSapiens/SmNZd1M5ZkZERFgxUG9FOHpCTC9EQQ','https://buenosaires.gaycities.com/bathhouses/307730-homosapiens','https://spartacus.gayguide.travel/saunas/southamerica/argentina/buenosaires/80860_Homo%2BSapiens']::text[]),
      'topic_evidence', jsonb_build_object(
        'queue_wait', jsonb_build_object('status','simple_towel_locker_entry_with_friday_afternoon_capacity_and_large_three_level_orientation_need','source_urls',to_jsonb(array['https://www.travelgay.com/venue/homo-sapiens-buenos-aires','https://buenosaires.gaycities.com/bathhouses/307730-homosapiens']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'best_nights', jsonb_build_object('status','afternoon_led_friday_busy_weekend_younger_and_daylight_terrace_variation_before_2200_close','source_urls',to_jsonb(array['https://qlist.app/venues/Buenos-Aires/HomoSapiens/SmNZd1M5ZkZERFgxUG9FOHpCTC9EQQ','https://buenosaires.gaycities.com/bathhouses/307730-homosapiens']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'crowd_mix', jsonb_build_object('status','men_only_mostly_local_wide_age_older_bear_core_and_younger_weekend_low_attitude_social_mix','source_urls',to_jsonb(array['https://qlist.app/venues/Buenos-Aires/HomoSapiens/SmNZd1M5ZkZERFgxUG9FOHpCTC9EQQ','https://www.travelgay.com/venue/homo-sapiens-buenos-aires']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'dress_code', jsonb_build_object('status','towel_and_locker_sauna_norm_with_optional_shower_sandals_provided_safer_sex_materials_backup_and_explicit_consent','source_urls',to_jsonb(array['https://www.travelgay.com/venue/homo-sapiens-buenos-aires','https://spartacus.gayguide.travel/saunas/southamerica/argentina/buenosaires/80860_Homo%2BSapiens']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','friendly_attentive_discreet_staff_consensus_balanced_against_broken_facility_hot_water_cleaning_and_wear_reports','source_urls',to_jsonb(array['https://qlist.app/venues/Buenos-Aires/HomoSapiens/SmNZd1M5ZkZERFgxUG9FOHpCTC9EQQ','https://www.travelgay.com/venue/homo-sapiens-buenos-aires']::text[]),'checked_at','2026-08-07T00:00:00Z')
