        'crowd_mix', jsonb_build_object('status','student_young_local_exchange_traveller_and_queer_friendly_mixed_crowd_without_lgbtq_majority_evidence','source_urls',to_jsonb(array['https://www.tripadvisor.com/Attraction_Review-g312741-d2155732-Reviews-Hype-Buenos_Aires_Capital_Federal_District.html','https://www.kikaclub.com.ar/']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'dress_code', jsonb_build_object('status','smart_casual_palermo_norm_without_precise_published_ban_list_and_strong_secure_belonging_need','source_urls',to_jsonb(array['https://www.kikaclub.com.ar/','https://www.tripadvisor.co/Attraction_Review-g312741-d2486896-Reviews-Kika_Club-Buenos_Aires_Capital_Federal_District.html']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','bartender_speed_praise_balanced_against_security_table_foreigner_treatment_and_lost_property_complaints','source_urls',to_jsonb(array['https://www.kikaclub.com.ar/','https://www.tripadvisor.co/Attraction_Review-g312741-d2486896-Reviews-Kika_Club-Buenos_Aires_Capital_Federal_District.html']::text[]),'checked_at','2026-08-07T00:00:00Z')
