        'best_nights', jsonb_build_object('status','daytime_coffee_brunch_identity_with_later_weekend_cocktail_and_calendar_led_drag_art_music_fetish_events','source_urls',to_jsonb(array['https://buenosaires.gob.ar/gcaba_historico/pride-cafe','https://www.timeout.com/buenos-aires/proposals-for-the-lgbtiq-community-in-buenos-aires','https://wanderlog.com/place/details/1521329/pride-cafe']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'crowd_mix', jsonb_build_object('status','lgbtq_local_couple_friend_worker_and_international_historic_centre_visitor_integrated_daytime_mix','source_urls',to_jsonb(array['https://buenosaires.gob.ar/gcaba_historico/pride-cafe','https://holasantelmo.ar/pride-cafe/','https://wanderlog.com/place/details/1521329/pride-cafe']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'dress_code', jsonb_build_object('status','no_everyday_code_with_cafe_work_evening_and_event_specific_leather_style_plus_consent_boundary','source_urls',to_jsonb(array['https://www.timeout.com/buenos-aires/proposals-for-the-lgbtiq-community-in-buenos-aires','https://wanderlog.com/place/details/1521329/pride-cafe']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','historic_and_majority_safe_cordial_welcome_balanced_against_recent_delay_order_and_discrimination_complaint','source_urls',to_jsonb(array['https://buenosaires.gob.ar/gcaba_historico/pride-cafe','https://es.restaurantguru.com/PRIDE-CAFE-Buenos-Aires','https://wanderlog.com/place/details/1521329/pride-cafe']::text[]),'checked_at','2026-08-07T00:00:00Z')
