    (419::bigint, jsonb_build_object(
      'queue_wait', 'The discreet basement entrance is at Uriburu 1018 in central Buenos Aires—not the stored pin in Quilmes. Weekday afternoons can be sparse; after-work and Friday-Saturday nights build the stronger crowd. Pay, learn the layout and secure cash before entering the maze.',
      'best_nights', 'Friday and Saturday run latest and add younger men to a usually mature local crowd. Early evening suits a drink in the front lounge before exploring; late hours put more bodies into the labyrinth, cabins and public cubicles. A quiet weekday is better for first-time orientation than maximum action.',
      'crowd_mix', 'This is a men-only cruise bar with mostly local regulars, mature men, bears and a smaller tourist presence; younger guests are more visible on weekends. The lounge can be chatty while the maze is purposefully anonymous. It is not a general all-gender queer club.',
      'dress_code', 'Street clothes are normal at the bar, with no formal fashion gate. Choose simple layers and keep money or cards physically secure before cruising; theft warnings recur in older guest reports. Inside, direct communication matters more than clothing, and “no” needs no explanation.',
      'staff_inclusivity', 'Guides and guests often describe helpful staff, a relaxed attitude and a cleaner layout than expected. Other reports warn about theft and weak intervention, so do not outsource all safety to the desk. Tell staff immediately, note where an incident happened and leave if support feels vague.',
      'venue_classification', 'active_discreet_men_only_recoleta_barrio_norte_cruise_bar_at_uriburu_1018_with_front_lounge_large_labyrinth_cabins_gloryholes_mature_local_core_younger_weekend_shift_helpful_staff_reports_and_theft_caution',
      'identity_note', 'Zoom Gay Cruising Bar is at Presidente José Evaristo Uriburu 1018, CABA. The stored coordinates and Quilmes address are a geocoding error; it is a Recoleta/Barrio Norte venue near Facultad de Medicina.',
      'source_urls', to_jsonb(array['https://www.zoombuenosaires.com/','https://www.travelgay.com/venue/zoom-buenos-aires','https://gaytravelr.com/argentina/buenos-aires/cruise-bars/zoom-gay-cruising-bar','https://buenosaires.gaycities.com/bathhouses/190222-zoom-gay-cruising-bar','https://www.tripadvisor.cl/Attraction_Review-g312741-d2615746-Reviews-ZOOM-Buenos_Aires_Capital_Federal_District.html']::text[]),
      'topic_evidence', jsonb_build_object(
