        'best_nights', jsonb_build_object('status','weekend_seomyeon_food_bar_shopping_access_weekday_transit_efficiency_and_sky_lounge_breakfast_reset','source_urls',to_jsonb(array['https://www.arbanhotel.com/','https://www.booking.com/hotel/kr/arban.en-gb.html']::text[]),'checked_at','2026-08-07T00:00:00Z'),
