        'dress_code', jsonb_build_object('status','no_code_with_tourist_dinner_and_business_style_plus_shared_hotel_breakfast_etiquette','source_urls',to_jsonb(array['https://www.arbanhotel.com/','https://www.booking.com/hotel/kr/arban.en-gb.html']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','welcoming_staff_clean_spacious_room_and_value_consensus_with_shift_language_variability_and_no_exclusive_lgbtq_claim','source_urls',to_jsonb(array['https://www.booking.com/hotel/kr/arban.en-gb.html','https://www.booking.com/hotel/kr/arban.html']::text[]),'checked_at','2026-08-07T00:00:00Z')
