        'dress_code', jsonb_build_object('status','neat_casual_no_reported_fashion_gate_with_host_cues_turn_taking_and_no_photo_privacy_norm','source_urls',to_jsonb(array['https://queerintheworld.com/gay-busan-south-korea-travel-guide/','https://www.utopia-asia.com/pusbars.htm']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','friendly_crowd_but_limited_english_translation_need_and_korean_karaoke_price_side_dish_confirmation','source_urls',to_jsonb(array['https://www.travelgay.com/venue/blue','https://www.utopia-asia.com/pusbars.htm']::text[]),'checked_at','2026-08-07T00:00:00Z')
